// Package service is the Go port of the reputation model prototype (reputation/model.py).
// The formula is checked against golden cases generated by reputation/golden.py; change both together.
//
// ponytail: pure functions only. A Service with a repo (recompute after a closed order or a resolved
// dispute, as in the design document) comes with the order module in Spring.
package service

import (
	"math"

	"qolda/internal/domain/trust/model"
)

// weights of the score components; sum to 1
const (
	WeightRating = 0.45
	WeightOnTime = 0.25
	WeightClean  = 0.20
	WeightAge    = 0.10

	PriorWeight = 5   // "virtual" campus-average transactions every user starts with
	AgeFullDays = 365 // account age stops adding trust after a year

	// deposit = base × factor; factor is 1 for a new user and moves by 0.5 per DepositSpan points
	DepositSpan      = 20
	DepositMinFactor = 0.5
	DepositMaxFactor = 1.5
	DepositRound     = 100 // KZT

	ReciprocalWeight = 0.2 // a mutual vote counts as a fifth of a vote
)

// TrustScore — Bayesian estimate of every component, shrunk toward the campus average.
func TrustScore(h model.History, c model.Campus) model.Score {
	k := float64(PriorWeight)
	bayesRating := (c.Rating*k + h.RatingSum) / (k + h.RatingCount)
	rating := (bayesRating - 1) / 4
	onTime := (c.OnTime*k + h.OnTime) / (k + h.Returns)
	clean := (c.Clean*k + h.Closed - h.DisputesLost) / (k + h.Closed)
	age := math.Min(h.AgeDays/AgeFullDays, 1)

	score := 100 * (WeightRating*rating + WeightOnTime*onTime + WeightClean*clean + WeightAge*age)
	return model.Score{Score: clamp(score, 0, 100), Rating: rating, OnTime: onTime, Clean: clean, Age: age}
}

// NeutralScore — score of a user who just joined: the deposit anchor.
func NeutralScore(c model.Campus) float64 {
	return TrustScore(model.History{}, c).Score
}

// DepositFactor — 1 for a new user; lower for a better-than-new score, higher for a worse one.
func DepositFactor(score, neutral float64) float64 {
	return clamp(1-0.5*(score-neutral)/DepositSpan, DepositMinFactor, DepositMaxFactor)
}

// RecommendedDeposit rounds to DepositRound KZT, half to even like Python's round().
func RecommendedDeposit(baseDeposit, score, neutral float64) int64 {
	raw := baseDeposit * DepositFactor(score, neutral)
	return int64(math.RoundToEven(raw/DepositRound) * DepositRound)
}

// HistoryFromVotes — one vote per counterparty; weights (rater → weight, default 1) scale individual votes.
func HistoryFromVotes(votes []model.Vote, ageDays float64, weights map[int64]float64) model.History {
	h := model.History{AgeDays: ageDays}
	for _, v := range votes {
		w, ok := weights[v.Rater]
		if !ok {
			w = 1
		}
		h.RatingSum += w * v.Rating
		h.RatingCount += w
		h.Returns += w
		h.OnTime += w * v.OnTime
		h.Closed += w
		h.DisputesLost += w * (1 - v.Clean)
	}
	return h
}

// ReciprocityWeights — rater → weight for the votes about user: ReciprocalWeight if user has also rated
// that rater (they rented to each other, the pattern of a ring vouching for itself), 1 otherwise.
func ReciprocityWeights(user int64, votes map[int64][]model.Vote) map[int64]float64 {
	result := make(map[int64]float64, len(votes[user]))
	for _, v := range votes[user] {
		result[v.Rater] = 1
		for _, back := range votes[v.Rater] {
			if back.Rater == user {
				result[v.Rater] = ReciprocalWeight
				break
			}
		}
	}
	return result
}

// TrustScores — scores of all users; votes[u] are the votes about u, ages[u] is u's account age in days.
func TrustScores(votes map[int64][]model.Vote, ages map[int64]float64, c model.Campus) map[int64]float64 {
	result := make(map[int64]float64, len(ages))
	for u, age := range ages {
		result[u] = TrustScore(HistoryFromVotes(votes[u], age, ReciprocityWeights(u, votes)), c).Score
	}
	return result
}

func clamp(v, lo, hi float64) float64 {
	return math.Min(math.Max(v, lo), hi)
}
